describe('Multiple File Upload Feature', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="file-upload-section"]').should('be.visible');
  });

  it('should successfully upload multiple files at once', () => {
    const files = ['file1.txt', 'file2.pdf', 'file3.csv'];

    cy.get('[data-testid="file-input"]').selectFile(
      [
        'cypress/fixtures/file1.txt',
        'cypress/fixtures/file2.pdf',
        'cypress/fixtures/file3.csv'
      ],
      { force: true }
    );

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="upload-progress"]').should('be.visible');
    cy.get('[data-testid="upload-progress"]', { timeout: 10000 }).should('not.exist');

    files.forEach((fileName) => {
      cy.get('[data-testid="uploaded-files-list"]').should('contain', fileName);
    });

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', '3 files uploaded successfully');

    cy.get('[data-testid="file-count-badge"]').should('contain', '3');
  });

  it('should handle mixed file types and validate file sizes', () => {
    const largeFile = 'large_file.zip';
    const smallFile = 'small_file.txt';

    cy.get('[data-testid="file-input"]').selectFile(
      [
        'cypress/fixtures/large_file.zip',
        'cypress/fixtures/small_file.txt'
      ],
      { force: true }
    );

    cy.get('[data-testid="file-preview-list"]').within(() => {
      cy.get('[data-testid="file-item"]').should('have.length', 2);
      cy.get('[data-testid="file-size"]').first().should('contain', 'MB');
      cy.get('[data-testid="file-size"]').last().should('contain', 'KB');
    });

    cy.get('[data-testid="upload-button"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should display error when exceeding maximum file limit', () => {
    const maxFiles = 5;
    const filesToUpload = Array.from({ length: 7 }, (_, i) => `cypress/fixtures/file${i + 1}.txt`);

    cy.get('[data-testid="file-input"]').selectFile(filesToUpload, { force: true });

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', `Maximum ${maxFiles} files allowed`);

    cy.get('[data-testid="upload-button"]').should('be.disabled');
  });

  it('should allow removing individual files before upload', () => {
    cy.get('[data-testid="file-input"]').selectFile(
      [
        'cypress/fixtures/file1.txt',
        'cypress/fixtures/file2.pdf',
        'cypress/fixtures/file3.csv'
      ],
      { force: true }
    );

    cy.get('[data-testid="file-preview-list"]').within(() => {
      cy.get('[data-testid="file-item"]').should('have.length', 3);
      cy.get('[data-testid="remove-file-btn"]').eq(1).click();
    });

    cy.get('[data-testid="file-preview-list"]').within(() => {
      cy.get('[data-testid="file-item"]').should('have.length', 2);
      cy.get('[data-testid="file-item"]').should('not.contain', 'file2.pdf');
    });

    cy.get('[data-testid="upload-button"]').click();
    cy.get('[data-testid="success-message"]').should('contain', '2 files uploaded successfully');
  });

  it('should handle upload failure and allow retry', () => {
    cy.intercept('POST', '/api/upload', { statusCode: 500, body: { error: 'Server error' } }).as('uploadFail');

    cy.get('[data-testid="file-input"]').selectFile(
      [
        'cypress/fixtures/file1.txt',
        'cypress/fixtures/file2.pdf'
      ],
      { force: true }
    );

    cy.get('[data-testid="upload-button"]').click();
    cy.wait('@uploadFail');

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Upload failed');

    cy.intercept('POST', '/api/upload', { statusCode: 200, body: { success: true } }).as('uploadSuccess');

    cy.get('[data-testid="retry-button"]').click();
    cy.wait('@uploadSuccess');

    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should display upload progress for each file', () => {
    cy.get('[data-testid="file-input"]').selectFile(
      [
        'cypress/fixtures/file1.txt',
        'cypress/fixtures/file2.pdf'
      ],
      { force: true }
    );

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="progress-bar"]').should('be.visible');
    cy.get('[data-testid="progress-percentage"]').should('contain', '%');

    cy.get('[data-testid="file-progress-item"]').each(($item) => {
      cy.wrap($item).within(() => {
        cy.get('[data-testid="file-name"]').should('be.visible');
        cy.get('[data-testid="progress-indicator"]').should('be.visible');
      });
    });

    cy.get('[data-testid="success-message"]', { timeout: 10000 }).should('be.visible');
  });
});
